20	            card_types: vec![CardType::Instant],
21	            supertypes: vec![],
22	            subtypes: vec![],
23	            power: None,
24	            toughness: None,
25	            oracle_text: "Counter target spell. Return target permanent to its owner's hand.".into(),
26	            keywords: vec![],
27	            flashback_cost: None, continuous_effects: vec![], additional_cost: None, triggered_abilities: vec![],
28	        }
29	    }
30	
31	    fn target_requirement(&self) -> TargetRequirement {
32	        TargetRequirement::TwoTargets(
33	            Box::new(TargetRequirement::Spell),
34	            Box::new(TargetRequirement::PermanentWithFilter(TargetFilter::Any)),
35	        )
36	    }
