38	    fn is_valid_target(&self, state: &GameState, _caster: PlayerId, target: &Target, _registry: &CardRegistry) -> bool {
39	        match target {
40	            Target::Object(id) => {
41	                state.get_object(*id)
42	                    .map(|o| o.zone == Zone::Stack || o.zone == Zone::Battlefield)
43	                    .unwrap_or(false)
44	            }
45	            _ => false,
46	        }
47	    }
48	
49	    fn on_resolve(&self, state: &mut GameState, object_id: ObjectId, targets: &[Target], _registry: &CardRegistry) {
50	        // Counter the spell (first target)
51	        if let Some(Target::Object(spell_id)) = targets.first() {
52	            if let Some(obj) = state.get_object(*spell_id) {
53	                if obj.zone == Zone::Stack {
54	                    let name = obj.name.clone();
55	                    state.stack.retain(|e| e.as_spell() != Some(*spell_id));
56	                    state.move_spell_after_resolve(*spell_id);
57	                    state.log(LogLevel::Event, format!("{} was countered", name));
58	                }
59	            }
60	        }
61	        // Bounce the permanent (second target)
62	        if let Some(Target::Object(perm_id)) = targets.get(1) {
63	            if let Some(obj) = state.get_object(*perm_id) {
64	                if obj.zone == Zone::Battlefield {
65	                    let name = obj.name.clone();
66	                    state.move_object(*perm_id, Zone::Hand);
67	                    state.log(LogLevel::Event, format!("{} was returned to hand", name));
68	                }
69	            }
70	        }
71	        state.move_spell_after_resolve(object_id);
72	    }
73	}
